wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(117007223954263637918)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'search process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT patient_id,',
'           doctor_id,',
'           service_id,',
'           room_id,',
'           appointment_date,',
'           appointment_time,',
'           status',
'    INTO   :PATIENT_ID,',
'           :DOCTOR_ID,',
'           :P_SERVICE_ID,',
'           :ROOM_ID,',
'           :APP_DATE,',
'           :P_APP_TIME,',
'           :P_STATUS',
'    FROM appointments',
'    WHERE appointment_id = :APPOINTMENT_ID;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        apex_error.add_error (',
'            p_message => ''Appointment not found.'',',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(117007223668021637915)
,p_process_success_message=>'molodester!'
,p_internal_uid=>117007223954263637918
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(117007224250980637921)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'insert process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'INSERT INTO appointments (',
'    appointment_id,',
'    patient_id,',
'    doctor_id,',
'    service_id,',
'    room_id,',
'    appointment_date,',
'    appointment_time,',
'    status',
')',
'VALUES (',
'    :APPOINTMENT_ID,',
'    :PATIENT_ID,',
'    :DOCTOR_ID,',
'    :P_SERVICE_ID,',
'    :ROOM_ID,',
'    :APP_DATE,',
'    :P_APP_TIME,',
'    :P_STATUS',
');',
''))
