wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(117703811659373197436)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'search_process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT doctor_id,',
'           full_name,',
'           specialty_id,',
'           phone,',
'           email,',
'           room_id',
'    INTO   :P_DOCTOR_ID,',
'           :P_FULL_NAME,',
'           :P_SPECIALITY_ID,',
'           :P_PHONE,',
'           :P_EMAIL,',
'           :P_ROOM_ID',
'    FROM doctors',
'    WHERE doctor_id = :P_DOCTOR_ID;',
'',
'EXCEPTION',
